import java.util.*;

class Node {
  public int val;
  public List<Node> neighbors;
  public Node() { val = 0; neighbors = new ArrayList<>(); }
  public Node(int val) { this.val = val; neighbors = new ArrayList<>(); }
  public Node(int val, ArrayList<Node> neighbors) { this.val = val; this.neighbors = neighbors; }
}

class Solution {
  public Node cloneGraph(Node node) {
    if (node == null) return null;
    Map<Node, Node> clone = new HashMap<>();
    Deque<Node> queue = new ArrayDeque<>();
    clone.put(node, new Node(node.val));
    queue.offer(node);

    while (!queue.isEmpty()) {
      Node current = queue.poll();
      for (Node next : current.neighbors) {
        if (!clone.containsKey(next)) {
          clone.put(next, new Node(next.val));
          queue.offer(next);
        }
        clone.get(current).neighbors.add(clone.get(next));
      }
    }
    return clone.get(node);
  }
}

